create table if not exists public.users (
    id bigint generated by default as identity primary key,
    name text not null,
    email text not null unique,
    password_hash text not null,
    profile_picture text default 'default.png',
    role text default 'student',
    is_active boolean not null default true,
    last_login_at timestamptz,
    must_change_password boolean not null default false
);

alter table public.users
    add column if not exists is_active boolean not null default true;
alter table public.users
    add column if not exists last_login_at timestamptz;
alter table public.users
    add column if not exists must_change_password boolean not null default false;

create table if not exists public.system_settings (
    settings_key text primary key,
    settings_json text not null,
    updated_by bigint references public.users(id) on delete set null,
    updated_at timestamptz not null default current_timestamp
);

create table if not exists public.admin_activity_logs (
    id bigint generated by default as identity primary key,
    actor_user_id bigint references public.users(id) on delete set null,
    actor_name text not null default '',
    actor_email text not null default '',
    action text not null,
    target_user_id bigint,
    target_label text not null default '',
    details text not null default '',
    session_ip text not null default '',
    created_at timestamptz not null default current_timestamp
);

alter table public.admin_activity_logs
    add column if not exists session_ip text not null default '';

create table if not exists public.report_card_uploads (
    id bigint generated by default as identity primary key,
    user_id bigint not null references public.users(id) on delete cascade,
    original_filename text not null,
    content_type text not null,
    file_data bytea not null,
    uploaded_at timestamptz not null default current_timestamp,
    ocr_status text not null default 'needs_review',
    is_flagged boolean not null default false,
    flag_note text,
    student_name text not null default '',
    student_number text not null default '',
    extracted_subjects text not null default '',
    extracted_gwa text not null default '',
    ocr_error text,
    processed_at timestamptz
);

alter table public.report_card_uploads
    add column if not exists ocr_status text not null default 'needs_review',
    add column if not exists is_flagged boolean not null default false,
    add column if not exists flag_note text,
    add column if not exists student_name text not null default '',
    add column if not exists student_number text not null default '',
    add column if not exists extracted_subjects text not null default '',
    add column if not exists extracted_gwa text not null default '',
    add column if not exists ocr_error text,
    add column if not exists processed_at timestamptz;

create table if not exists public.student_profiles (
    id bigint generated by default as identity primary key,
    user_id bigint not null references public.users(id) on delete cascade,
    student_number text,
    first_name text,
    middle_initial text,
    last_name text,
    course text,
    gwa text,
    subjects text,
    recommendation text,
    strand text,
    upload_date text,
    grades text,
    report_card_upload_id bigint references public.report_card_uploads(id) on delete set null
);

alter table public.student_profiles
    add column if not exists report_card_upload_id bigint
    references public.report_card_uploads(id) on delete set null;

create table if not exists public.course_recommendation_history (
    id bigint generated by default as identity primary key,
    profile_id bigint not null references public.student_profiles(id) on delete cascade,
    recommendations text not null,
    generated_at timestamptz not null default current_timestamp
);

select profiles.id, profiles.recommendation
from public.student_profiles profiles
where profiles.recommendation is not null and profiles.recommendation != ''
    and not exists (
        select 1 from public.course_recommendation_history history
        where history.profile_id = profiles.id
    );

create index if not exists student_profiles_user_id_idx
    on public.student_profiles(user_id);

create table if not exists public.course_training_data (
    id bigint generated by default as identity primary key,
    course text not null unique,
    features jsonb not null,
    description text not null
);

on conflict (course) do update set features = excluded.features, description = excluded.description;

-- 169 additional courses to bring the catalog to 200 total
on conflict (course) do update set features = excluded.features, description = excluded.description;

-- Reuse the existing academic feature profiles, then retain only university programs.
create temporary table if not exists university_course_catalog (
    course text primary key,
    source text not null
);
truncate university_course_catalog;

select catalog.course, source.features,
    case catalog.course
        when 'BS in Aircraft Maintenance and Technology' then 'Study aircraft inspection, maintenance, and repair for safe aviation operations.'
        when 'Aircraft Maintenance Technology' then 'Study aircraft inspection, maintenance, and repair for safe aviation operations.'
        when 'BS in Aviation Electronics Technology' then 'Study aircraft electrical systems, avionics, and aviation electronics maintenance.'
        when 'Aviation Electronics Technology' then 'Study aircraft electrical systems, avionics, and aviation electronics maintenance.'
        when 'Bachelor of Elementary Education' then 'Prepare to teach and support learners across elementary school subjects.'
        when 'Bachelor of Secondary Education' then 'Prepare to teach and support learners at the secondary school level.'
        when 'BS in Digital Engineering' then 'Apply digital tools, data, and engineering methods to design technical systems.'
        when 'BS in Naval Architecture and Marine Engineering' then 'Study ship design, vessel structures, and marine engineering systems.'
        else source.description
    end
from university_course_catalog catalog
join public.course_training_data source on source.course = catalog.source
on conflict (course) do update set features = excluded.features, description = excluded.description;

delete from public.course_training_data
where course not in (select course from university_course_catalog);
drop table university_course_catalog;
